"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[5834],{6414:e=>{e.exports=JSON.parse('{"functions":[{"name":"detach","desc":"Detaches a chunk\'s instances and queues them for piecewise destruction.\\n\\nDetaching first is load-bearing: letting the subtree linger in Workspace\\nwhile a slow destroy queue drains measured mean 31.54ms against 12.48ms.","params":[{"name":"world","desc":"","lua_type":"jecs.World"},{"name":"chunkEntity","desc":"","lua_type":"Entity"}],"returns":[],"function_type":"static","source":{"line":32,"path":"src/main/server/utils/demolition.luau"}},{"name":"drain","desc":"Destroys queued chunk contents until the frame\'s shared deadline.\\n\\nWalks a folder one child at a time rather than calling `Destroy` on the root:\\ndestroying a whole chunk atomically is the single largest hitch the pipeline\\ncan produce. Nested folders are pushed onto the queue rather than recursed\\ninto, so the walk stays interruptible at any depth.\\n\\nAlways destroys at least one thing per call, so a blown budget slows the\\nqueue instead of stalling it.","params":[{"name":"world","desc":"","lua_type":"jecs.World"},{"name":"deadline","desc":"`os.clock()` value to stop at.","lua_type":"number"}],"returns":[],"function_type":"static","source":{"line":63,"path":"src/main/server/utils/demolition.luau"}}],"properties":[],"types":[],"name":"demolition","desc":"Tearing chunks down: detaching them at once, then destroying their contents\\ngradually.\\n\\nThe two halves are deliberately asymmetric. Detaching is atomic because the\\nengine bills for instances *resident* in the world each frame \u2014 the moment a\\nchunk leaves Workspace it stops costing streaming, physics and replication,\\nand spreading that detach across frames measured mean 17.89ms against 10.39ms.\\nDestroying is incremental because it is pure cleanup on instances that are\\nalready costing nothing.","tags":["server-util"],"realm":["Server"],"source":{"line":16,"path":"src/main/server/utils/demolition.luau"}}')}}]);